function openModal(title,body,{submit='保存',onSubmit=null,wide=false,footer='',context={}}={}){
  if(!dialog.open)rememberView();placeToast(document.body);if(dialog.open)dialog.close();modalContext=context;
  dialog.className=wide?'wide':'';
  dialog.innerHTML=`<div class="dialog-header"><div><span class="eyebrow">NO GAME NO LIFE</span><h2 id="dialog-title">${e(title)}</h2></div><button type="button" class="close-button" data-action="close" aria-label="关闭">×</button></div><form id="modal-form"><div class="dialog-body">${body}<p id="form-error" class="form-error" role="alert" hidden></p></div><div class="dialog-footer"><span>${footer}</span><div><button type="button" class="secondary" data-action="close">${onSubmit?'取消':'关闭'}</button>${onSubmit?`<button type="submit" class="primary">${submit}</button>`:''}</div></div></form>`;
  const op=D.uid();
  $('#modal-form').onsubmit=async event=>{
    event.preventDefault();if(busy||!onSubmit)return;busy=true;const button=event.submitter;button.disabled=true;$('#form-error').hidden=true;
    try{await onSubmit(new FormData(event.currentTarget),op,event.currentTarget);}catch(error){showError(error);}finally{busy=false;if(button.isConnected)button.disabled=false;if(channelPending)await refresh();}
  };
  dialog.showModal();placeToast(dialog);globalThis.NGNLNative?.setEditorOpen?.(true);
}
async function closeModal(options={}){const refreshNeeded=options.refresh!==false||!!tasks.active;const onClose=modalContext.onClose,returnTo=await tasks.leave();const finish=()=>{placeToast(document.body);dialog.close();modalContext={};globalThis.NGNLNative?.setEditorOpen?.(false);requestAnimationFrame(restoreFocus);if(ui.pendingNativeAction==='choose-activity'){ui.pendingNativeAction=null;setTimeout(chooseActivity,0);}};if(records.active)return records.leave().then(async()=>{await refresh();finish();});if(refreshNeeded)await refresh();finish();if(options?.resume!==false)await (returnTo??onClose)?.();}
function entityReplace(s,list,original,next){const current=s[list].find(x=>x.id===next.id);if(original&&JSON.stringify(current)!==JSON.stringify(original))throw new Error('这项内容已在其他页面变化，请重新打开核对；填写已保留，原内容未覆盖');if(!original&&current)return s;if(original)s[list][s[list].findIndex(x=>x.id===next.id)]=next;else s[list].push(next);return s;}
