      const selectedPlan=state.plans.find(p=>p.id===ui.detailPlanId);const periodImpacts=selectedPlan?periodOverview(state,selectedPlan).skills.map(before=>{const after=periodOverview(candidate,selectedPlan).skills.find(g=>g.skill.id===before.skill.id);return after&&before.periodPoints!==after.periodPoints?`${e(before.skill.name)} 本期实录 ${V.num(before.periodPoints)} → ${V.num(after.periodPoints)} 分`:'';}).filter(Boolean):[];
      const plans=state.plans.map(p=>({p,b:D.planProgress(state,p).minutes,a:D.planProgress(candidate,p).minutes})).filter(x=>x.a!==x.b);
      $('#edit-preview').hidden=false;$('#edit-preview').innerHTML=`<h3>保存后会怎样</h3><p>${isEdit?V.duration(oldDuration)+' → ':''}${V.duration(newDuration)}${isEdit&&newDuration<oldDuration?'；缩短范围留为空白。':''}</p>${[...impacts,...periodImpacts].map(v=>`<p>${v}</p>`).join('')}${plans.map(x=>`<p>${e(x.p.title)}：${V.num(x.b)} → ${V.num(x.a)} 分钟，目标 ${V.num(x.p.targetMinutes)} 分钟不变。</p>`).join('')}<p class="quiet-note">照片、感受、独立成果和适用自评保留。今日计时继续。若有重叠，保存会拒绝，不覆盖其他段。</p>`;
