function sessionDetails(id){const s=state.sessions.find(x=>x.id===id);openModal(s.name,`<div class="detail-facts"><p>${D.dateKey(s.start,state.timeZone)} ${V.clock(s.start,state.timeZone)} — ${D.dateKey(s.end,state.timeZone)} ${V.clock(s.end,state.timeZone)}</p><strong>${V.duration((s.end-s.start)/60000)}</strong><p>${s.source==='manual'?'人工确认补记':'手动计时'} · ${s.precision==='minute'?'分钟精度':'秒精度'}</p></div><div class="inline-actions"><button type="button" class="secondary" data-action="leave-example" data-id="${e(id)}">留这次表现</button><button type="button" class="primary" data-action="moment-for-session" data-id="${e(id)}">补充文字或照片</button><button type="button" class="secondary" data-action="edit-session" data-id="${e(id)}">修正时间</button><button type="button" class="text-button" data-action="remove-session" data-id="${e(id)}">移除误记</button></div>${state.moments.filter(m=>m.sessionId===id).map(V.momentContent).join('')}`);}
