function assessSkill(id,index){const s=state.skills.find(s=>s.id===id),st=s.stages[index],g=D.growthProgress(state,s);openModal('对照标准，确认这次表现',`<span class="tag">${e(s.name)} · 第${index+1}阶段</span><h3 class="standard-heading">${e(st.name)}</h3><div class="standard-card"><p>${e(st.standard)}</p><p class="quiet-note">按你为这项技能选择的目标范围与适用条件判断。可以借助目标允许的资料或工具；完成文件本身不自动证明所有要求。</p></div><p class="quiet-note">${g.growthPoints<s.stages.slice(0,index+1).reduce((n,s)=>n+s.q*s.levels,0)?'投入尚未到本段门槛，自评仍可保存；投入刻度不会凭空增加。':'普通等级自动推进；本次确认只保留你的能力判断，不发额外积分。'}</p><label>表现或依据 · 选填<textarea name="note" maxlength="20000" placeholder="可以描述真实表现，也可以暂时不留材料"></textarea></label><label class="check"><input type="checkbox" name="confirm" required>我已对照这张标准卡，确认自己的表现符合要求</label>`,{submit:'确认这次自评',onSubmit:async(f,op)=>{const assessment={id:D.uid(),skillId:id,stageIndex:index,at:Date.now(),note:String(f.get('note')||''),revoked:false,standard:st.standard};await save(latest=>{const current=latest.skills.find(x=>x.id===id);if(current.stages[index].standard!==st.standard)throw new Error('标准已变化，请重新对照');latest.assessments.push(assessment);return latest;},{operationId:op});closeModal();toast('自评已保留');}});}
function completePlan(id){const p=state.plans.find(x=>x.id===id);openModal(p.completedAt?'已留下这次达成':'确认成果完成',`<span class="tag">${e(p.title)}</span><h3 class="standard-heading">${e(p.outcome)}</h3><p>${p.completedAt?'已确认于 '+D.dateKey(p.completedAt,state.timeZone)+'。如果当时判断有误，可以更正完成状态。':'请确认实际成果已经完成。投入达到目标不会代替这一步，也不自动证明能力。'}</p><label>成果说明 · 选填<textarea name="outcomeNote" maxlength="10000">${e(p.outcomeNote||'')}</textarea></label><label class="check"><input type="checkbox" name="completed" ${p.completedAt?'checked':''}>成果已实际完成</label>`,{submit:'保存成果状态',onSubmit:async(f,op)=>{const next={...p,completedAt:f.has('completed')?(p.completedAt??Date.now()):null,outcomeNote:String(f.get('outcomeNote')||'')};await save(s=>entityReplace(s,'plans',p,next),{operationId:op});closeModal();toast(next.completedAt?'阶段里程碑已留下 ✦':'成果状态已更正');}});}
const momentEditor=(id=null,sessionId=null)=>openDiary(id,sessionId,null,'daily',!id&&!sessionId&&ui.page==='overview'?ui.date:null);
const dayNote=date=>openDiary('daily:'+date,null,null,'daily',date);
function recoveryDialog(){
  const r=state.running;if(!r)return;const now=Date.now();
  openModal('回来后，核对一下这段计时',`<h3>${e(r.name)}</h3><p>${D.dateKey(r.start,state.timeZone)} ${V.clock(r.start,state.timeZone)} 开始，已保存到 ${D.dateKey(r.confirmedUntil,state.timeZone)} ${V.clock(r.confirmedUntil,state.timeZone,true)}。</p><p class="quiet-note">这段计时的运行连续性需要核对。下方选择只处理尚未确认的尾段；已保存记录保持。继续会由你确认这期间一直在做同一件事。</p><button type="button" class="primary full-width" data-action="organize-range">整理这段记录 · 多段与留白</button><label>快速确认<select name="mode" id="recovery-mode"><option value="keep">这期间仍在做同一件事，继续计时</option><option value="end">结束到我确定的时间，其后留空白</option></select></label><label id="recovery-boundary-label" hidden>确定结束时间<input type="datetime-local" name="boundary" step="1" value="${D.localInput(r.confirmedUntil,state.timeZone,true)}"></label>`,{submit:'确认并保存',onSubmit:async(f,op)=>{const mode=f.get('mode'),boundary=mode==='keep'?Date.now():D.parseEditedLocal(f.get('boundary'),r.confirmedUntil,state.timeZone);await save(s=>{if(s.running?.id!==r.id)throw new Error('当前计时已在其他页面切换，请重新核对');return D.resolveRunning(s,boundary,mode,Date.now());},{operationId:op});needsRecovery=false;render();closeModal();toast('已按你的确认恢复');}});
  $('#recovery-mode').onchange=event=>{$('#recovery-boundary-label').hidden=event.target.value==='keep';};
}
function exportNotice(result,webMessage){toast(result.native?(result.saved?'文件已保存到你选择的位置':'已取消导出，应用记录未变化'):webMessage);}
async function backup(){await refresh();const result=await downloadText(`NGNL-完整备份-${D.dateKey(Date.now(),state.timeZone)}.json`,JSON.stringify(await repo.exportBackup()));exportNotice(result,'备份下载已发起，请保管下载文件');}
async function rollbackExport(original=false){
 const point=await repo.recoveryPoint('before-schema4');
 if(!original){openModal('新版数据与回退','<p>投入型培养、背景、周安排和待核对记录需要新版完整备份。旧格式无法完整承载，不能当作无损回退。</p><button type="button" class="primary" data-action="backup">导出当前完整备份</button>');return;}
 if(!point?.backup)throw Error('本机没有旧版升级前快照');
 const result=await downloadText('NGNL-升级前完整备份.json',JSON.stringify(point.backup));exportNotice(result,'升级前完整备份下载已发起');
}
function importPreview(next,kind='导入备份',drafts=[],assets=[]){const revision=state.revision,photos=next.moments.reduce((n,m)=>n+m.photos.length,0);openModal(kind,`<div class="preview-box"><h3>将恢复这份完整数据</h3><p>${next.sessions.length} 条已结束活动 · ${next.skills.length} 个培养项 · ${next.plans.length} 个阶段</p><p>${next.moments.length} 个片段 · ${photos} 张照片${next.running?' · 有运行中计时，恢复后须核对尾段':''}</p><p>数据时区：${e(next.timeZone)} · ${drafts.length} 份草稿也将恢复</p></div><p>确认后会替换当前数据空间里的整份记录。不会与当前记录相加。替换前自动保存一个本机恢复点，可在本页恢复。</p><label class="check"><input name="confirm" type="checkbox" required>我确认使用这份备份替换当前数据</label>`,{submit:'确认替换并恢复',onSubmit:async()=>{state=await repo.replace(next,revision,{drafts,assets});ui.drafts=await repo.listDrafts();ui.assets=await repo.listAssets();globalThis.NGNLNative?.disableRuntime?.();needsRecovery=!!state.running;render();closeModal();toast('完整数据已恢复，原数据已留本机恢复点');}});}
function exportRange(){const start=ui.rangeStart||ui.date,end=ui.rangeEnd||ui.date;openModal('按范围整理给 AI',`<div class="form-row"><label>开始日期<input type="date" name="start" value="${start}" required></label><label>结束日期<input type="date" name="end" value="${end}" required></label></div><p>导出一份可读的 Markdown，包含原始活动、你写的图文说明、整体感受和当期成果。照片本体不在文字导出中，需完整备份保留；不会自动发给 AI。</p>`,{submit:'下载文字导出',onSubmit:async f=>{const a=f.get('start'),b=f.get('end');rangeCheck(a,b);await refresh();let text=`# NO GAME NO LIFE 记录\n\n范围：${a} 至 ${b}；时区：${state.timeZone}\n\n以下为用户保存的材料。投入不等于能力。不要推测缺失时间或代写感受。\n`;
    for(let d=a;d<=b;d=D.addDays(d,1)){const rows=D.sessionsInRange(state,d,d),moments=state.moments.filter(m=>D.dateKey(m.at,state.timeZone)===d||rows.some(r=>r.id===m.sessionId));if(!rows.length&&!moments.length&&!state.dailyNotes[d]?.text)continue;text+=`\n## ${d}\n`;for(const row of rows)text+=`\n- ${V.clock(row.start,state.timeZone)}—${V.clock(row.end,state.timeZone)} ${row.name}（${V.duration((row.end-row.start)/60000)}，${row.source==='manual'?'人工补记':'计时'}，${row.precision==='minute'?'分钟精度':'秒精度'}）`;for(const m of moments)text+=`\n\n### ${m.title||state.sessions.find(r=>r.id===m.sessionId)?.name||'独立片段'}\n${m.text}${m.photos.length?'\n照片：'+m.photos.map(p=>p.name).join('、')+'（本体另见完整备份）':''}`;if(state.dailyNotes[d]?.text)text+=`\n\n整体感受：${state.dailyNotes[d].text}\n`;}
    for(const p of state.plans.filter(p=>p.startDate<=b&&p.endDate>=a))text+=`\n\n## 阶段：${p.title}\n${p.startDate}—${p.endDate}\n时间进度：${V.num(D.planProgress(state,p).minutes)}/${p.targetMinutes}分钟\n成果：${p.outcome||'未设置'}；${p.completedAt?'用户已确认完成':'未确认完成'}\n${p.outcomeNote||''}`;
    const result=await downloadText(`NGNL-回看-${a}-${b}.md`,text,'text/markdown;charset=utf-8');closeModal();exportNotice(result,'文字导出已发起');}});}
async function storageInfo(){if(ui.native){if($('#storage-status'))$('#storage-status').textContent='当前应用的本地数据';if($('#offline-status'))$('#offline-status').textContent='应用资源已随安装包保存';return;}let persistent=false;try{persistent=await navigator.storage?.persisted?.();}catch{}if($('#storage-status'))$('#storage-status').textContent=persistent?'已获持久保留许可':'浏览器管理 · 可请求保留';const sw='serviceWorker'in navigator?await navigator.serviceWorker.getRegistration().catch(()=>null):null;if($('#offline-status'))$('#offline-status').textContent=sw?.waiting?'更新已下载，关闭此网址所有页面后生效；记录保留':sw?.active?'已缓存应用资源（照片在本地数据库）':window.isSecureContext?'尚未缓存，请在线重开一次':'当前 HTTP 来源不支持离线缓存';}
const seenReminders=new Set();
function tick(){if(state&&!ui.native&&!document.hidden){const reminder=reminderProjection(state);if(reminder&&reminder.at<=Date.now()&&!seenReminders.has(reminder.id)){seenReminders.add(reminder.id);toast('已到你预计的结束时间。可继续、切换或停止，时间尚未自动确认。');save(s=>{const r=s.reminders.find(x=>x.id===reminder.id);if(r)r.status='delivered';return s;}).catch(showError);}} if(!state)return;if(!diary.active&&!dialog.open&&!document.hidden&&renderedBookDay!==D.dateKey(Date.now(),state.timeZone)){render();return;}const r=state.running;const secs=r?Math.max(0,Math.floor((Date.now()-r.start)/1000)):0,h=String(Math.floor(secs/3600)).padStart(2,'0'),m=String(Math.floor(secs%3600/60)).padStart(2,'0'),s=String(secs%60).padStart(2,'0');document.querySelectorAll('[data-live]').forEach(el=>{const value=r?`${h}:${m}:${s}`:'00:00';el.textContent=value;if(el.classList.contains('r-digits')){const size=parseFloat(getComputedStyle(el).getPropertyValue('--timer-size'))||48;el.style.fontSize=size+'px';const range=document.createRange();range.selectNodeContents(el);const width=range.getBoundingClientRect().width;if(width>el.clientWidth)el.style.fontSize=Math.max(18,size*el.clientWidth/width)+'px';}});document.querySelectorAll('[data-live-small]').forEach(el=>el.textContent=`${h}:${m}:${s}`);}

